mapper.update:
UPDATE community_report r
SET r.content = NULL
WHERE r.content IS NOT NULL
  AND (
        r.reviewed_at <= #{cutoff}
        OR (
            r.reviewed_at IS NULL
            AND (
                (r.target_type = 'POST' AND EXISTS (
                    SELECT 1
                    FROM community_post t
                    WHERE t.id = r.target_id
                      AND t.status = 'HIDDEN'
                      AND t.updated_at <= #{cutoff}
                ))
                OR (r.target_type = 'COMMENT' AND EXISTS (
                    SELECT 1
                    FROM community_comment t
                    WHERE t.id = r.target_id
                      AND t.status = 'HIDDEN'
                      AND t.updated_at <= #{cutoff}
                ))
            )
        )
      )
LIMIT #{limit}
